<script setup lang="ts">
import { useRecurringRulesQuery, usePauseRule, useResumeRule } from '@/api/queries/domainQueries'; import LcButton from '@/components/ui/LcButton.vue'; import LcCard from '@/components/ui/LcCard.vue'; import LcEmptyState from '@/components/ui/LcEmptyState.vue'
const rules = useRecurringRulesQuery(); const pause = usePauseRule(); const resume = useResumeRule(); const field = (item: unknown, key: string) => item && typeof item === 'object' ? String((item as Record<string, unknown>)[key] ?? '—') : '—'
</script>
<template><section class="grid gap-6"><h1 class="font-display text-3xl font-bold">Recurring report rules</h1><LcEmptyState v-if="(rules.data.value ?? []).length === 0" title="No recurring rules" description="Creation is supported by the API; detailed scheduling UI is intentionally conservative."/><LcCard v-for="rule in rules.data.value ?? []" :key="field(rule, 'id')"><h2 class="font-display text-lg font-bold">Every {{ field(rule, 'intervalValue') }} {{ field(rule, 'intervalUnit') }}</h2><p class="text-sm text-textMuted">Next run: {{ field(rule, 'nextRunAt') }} · Paused: {{ field(rule, 'pausedAt') }}</p><div class="mt-3 flex gap-2"><LcButton variant="secondary" @click="pause.mutate(field(rule, 'id'))">Pause</LcButton><LcButton variant="secondary" @click="resume.mutate(field(rule, 'id'))">Resume</LcButton></div></LcCard></section></template>
